"""Day 078: compare linearizable vs eventual write latency."""
from __future__ import annotations
import random
import statistics

def simulate(mode: str, n: int, rtt_ms: float, partitioned: bool) -> list[float]:
lat = []
for _ in range(n):
base = random.uniform(0.5, 2.0)
if mode == "linearizable":
if partitioned:
continue
lat.append(base + rtt_ms * 2)
else:
lat.append(base + rtt_ms * 0.1)
return lat

def main() -> None:
random.seed(42)
rtt = 5.0
for part in (False, True):
print(f"\n=== partition={part} ===")
for mode in ("linearizable", "eventual"):
samples = simulate(mode, 200, rtt, part)
if not samples:
print(f"{mode}: UNAVAILABLE")
else:
p95 = sorted(samples)[190]
print(f"{mode}: mean={statistics.mean(samples):.2f}ms p95={p95:.2f}ms n={len(samples)}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 079: Lamport logical clock simulation."""
from __future__ import annotations

class Lamport:
def __init__(self, name: str) -> None:
self.name = name
self.t = 0
self.log: list[tuple[int, str]] = []

def local(self, label: str) -> None:
self.t += 1
self.log.append((self.t, f"{self.name} local {label}"))

def send(self, label: str) -> int:
self.t += 1
self.log.append((self.t, f"{self.name} send {label}"))
return self.t

def receive(self, ts: int, label: str) -> None:
self.t = max(self.t, ts) + 1
self.log.append((self.t, f"{self.name} recv {label}"))

def main() -> None:
a, b, c = Lamport("A"), Lamport("B"), Lamport("C")
a.local("start")
ts1 = a.send("to B")
b.receive(ts1, "from A")
b.local("work")
ts2 = b.send("to C")
c.receive(ts2, "from B")
c.local("finish")
print("=== Lamport event log ===")
for proc in (a, b, c):
for t, msg in proc.log:
print(f"L={t:2d} {msg}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 080: vector clock causal ordering."""
from __future__ import annotations

def dominates(a: list[int], b: list[int]) -> bool:
return all(x >= y for x, y in zip(a, b)) and any(x > y for x, y in zip(a, b))

def concurrent(a: list[int], b: list[int]) -> bool:
return not dominates(a, b) and not dominates(b, a)

def main() -> None:
v0, v1, v2 = [1, 0, 0], [1, 1, 0], [0, 0, 1]
print("=== Vector clock relations ===")
print(f"v0={v0} -> v1={v1} causal={dominates(v0, v1)}")
print(f"v0={v0} vs v2={v2} concurrent={concurrent(v0, v2)}")
buffer = [("m1", v1), ("m2", v2)]
seen = [0, 0, 0]
delivered = []
for msg, vec in buffer:
if dominates(vec, seen) or vec == seen:
seen = [max(seen[i], vec[i]) for i in range(3)]
delivered.append(msg)
else:
print(f"BLOCKED {msg} vec={vec} seen={seen}")
print("Delivered:", delivered)

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 082: simple majority consensus simulator."""
from __future__ import annotations

def round_vote(proposals: dict[int, str], alive: set[int]) -> str | None:
votes: dict[str, int] = {}
for node, val in proposals.items():
if node in alive:
votes[val] = votes.get(val, 0) + 1
if not votes:
return None
winner, count = max(votes.items(), key=lambda x: x[1])
return winner if count > len(alive) / 2 else None

def main() -> None:
nodes = {0, 1, 2}
scenarios = [
("clean majority", {0: "A", 1: "A", 2: "B"}, nodes),
("split vote", {0: "A", 1: "B", 2: "C"}, nodes),
("lost minority", {0: "A", 1: "A"}, nodes - {2}),
("lost quorum", {0: "A"}, {0}),
]
print("=== Consensus simulator ===")
for label, props, alive in scenarios:
decision = round_vote(props, alive)
print(f"{label}: alive={sorted(alive)} -> {decision or 'NO DECISION'}")

if __name__ == "__main__":
main()

