#!/usr/bin/env python3
"""Day 084: batch log analysis pipeline."""
from __future__ import annotations
import hashlib
from collections import Counter

LOGS = [
"GET /api/users 200 12",
"GET /api/users 500 45",
"POST /api/orders 201 30",
"GET /api/users 200 10",
"GET /api/health 200 1",
"CORRUPT LINE",
"GET /api/orders 404 8",
]

def parse(line: str) -> tuple[str, int] | None:
parts = line.split()
if len(parts) != 4 or not parts[2].isdigit():
return None
return f"{parts[0]} {parts[1]}", int(parts[2])

def run(lines: list[str], strict: bool) -> dict:
endpoints: Counter = Counter()
errors = total = 0
for line in lines:
rec = parse(line)
if rec is None:
if strict:
raise ValueError(f"bad line: {line!r}")
continue
ep, status = rec
total += 1
endpoints[ep] += 1
if status >= 400:
errors += 1
return {"total": total, "errors": errors, "top": endpoints.most_common(3)}

def digest(report: dict) -> str:
return hashlib.sha256(repr(report).encode()).hexdigest()[:12]

def main() -> None:
clean = [l for l in LOGS if l != "CORRUPT LINE"]
r1 = run(clean, strict=True)
r2 = run(clean, strict=True)
print("=== Batch log report (clean input) ===")
print(r1)
print(f"checksum run1={digest(r1)} run2={digest(r2)} match={digest(r1)==digest(r2)}")
try:
run(LOGS, strict=True)
except ValueError as e:
print(f"\nstrict mode on corrupt input: {e}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 086: mini MapReduce word count."""
from __future__ import annotations
from collections import defaultdict

DOCS = ["hello world", "hello mapreduce", "world of batch"]

def map_fn(doc: str) -> list[tuple[str, int]]:
return [(w, 1) for w in doc.split()]

def partition(key: str, n: int) -> int:
return hash(key) % n

def shuffle(pairs: list[tuple[str, int]], n: int) -> list[list[tuple[str, int]]]:
parts: list[list[tuple[str, int]]] = [[] for _ in range(n)]
for k, v in pairs:
parts[partition(k, n)].append((k, v))
return parts

def reduce_fn(pairs: list[tuple[str, int]]) -> dict[str, int]:
out: dict[str, int] = defaultdict(int)
for k, v in pairs:
out[k] += v
return dict(out)

def job(docs: list[str], parts: int = 2) -> dict[str, int]:
mapped = [p for d in docs for p in map_fn(d)]
shuffled = shuffle(mapped, parts)
merged: dict[str, int] = defaultdict(int)
for part in shuffled:
for k, v in reduce_fn(part).items():
merged[k] += v
return dict(merged)

def main() -> None:
r1 = job(DOCS)
r2 = job(DOCS[:2] + DOCS[2:]) # simulate retry of last split
print("=== MapReduce word count ===")
print(r1)
print(f"deterministic retry: {r1 == r2}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 087: partitioned hash join with skew demo."""
from __future__ import annotations
from collections import defaultdict

CLICKS = [(1, "p1"), (2, "p2"), (1, "p3"), (1, "p4"), (1, "p5")]
USERS = {1: "alice", 2: "bob"}

def partition(key: int, n: int) -> int:
return key % n

def hash_join(clicks, users, parts: int, salt: int = 1) -> list[tuple]:
buckets: list[list] = [[] for _ in range(parts)]
sizes = [0] * parts
for uid, page in clicks:
for s in range(salt):
k = (uid, s) if salt > 1 else uid
p = partition(uid if salt == 1 else hash(k) % 10_000, parts)
buckets[p].append((uid, page))
sizes[p] += 1
out = []
for part in buckets:
for uid, page in part:
out.append((users.get(uid, "?"), page))
return out, sizes

def main() -> None:
for salt in (1, 4):
joined, sizes = hash_join(CLICKS, USERS, 4, salt=salt)
print(f"\n=== salt={salt} partition sizes={sizes} max/min={max(sizes)/max(1,min(sizes)):.1f} ===")
print(f"rows={len(joined)}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 088: derived data ETL with versioned pointer."""
from __future__ import annotations
from collections import defaultdict

EVENTS = [
{"user": "u1", "type": "login", "ts": 1},
{"user": "u2", "type": "purchase", "ts": 2},
{"user": "u1", "type": "purchase", "ts": 3},
]

def build(events: list[dict]) -> dict[str, dict]:
profiles: dict[str, dict] = defaultdict(lambda: {"logins": 0, "purchases": 0})
for e in events:
p = profiles[e["user"]]
if e["type"] == "login":
p["logins"] += 1
else:
p["purchases"] += 1
return dict(profiles)

def validate(profiles: dict) -> bool:
return all(v["logins"] >= 0 and v["purchases"] >= 0 for v in profiles.values())

def main() -> None:
versions = {}
pointer = None
for ver in ("v1", "v2"):
data = build(EVENTS)
if ver == "v2":
data["u1"]["logins"] = -1 # bad deploy
versions[ver] = data
if validate(data):
pointer = ver
print(f"promoted {ver}: {data}")
else:
print(f"rejected {ver}: validation failed, pointer stays {pointer}")
print(f"\nactive pointer={pointer} serving={versions[pointer]}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 089: partitioned append-only event log."""
from __future__ import annotations

class Log:
def __init__(self, n: int) -> None:
self.parts: list[list[tuple[str, str]]] = [[] for _ in range(n)]

def append(self, key: str, value: str) -> tuple[int, int]:
p = hash(key) % len(self.parts)
self.parts[p].append((key, value))
return p, len(self.parts[p]) - 1

def read(self, part: int, offset: int) -> list[tuple[str, str]]:
return self.parts[part][offset:]

def ordered_per_key(log: Log) -> bool:
seen: dict[str, list[str]] = {}
for part in log.parts:
for key, val in part:
seen.setdefault(key, []).append(val)
return all(vals == sorted(vals, key=lambda x: int(x.split("-")[1])) for vals in seen.values())

def main() -> None:
log = Log(3)
for i in range(6):
p, off = log.append("user-1", f"evt-{i}")
print(f"append user-1 evt-{i} -> partition={p} offset={off}")
print(f"per-key order preserved: {ordered_per_key(log)}")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 090: consumer group assignment and offset commit."""
from __future__ import annotations

def assign(partitions: list[int], consumers: list[str]) -> dict[str, list[int]]:
mapping: dict[str, list[int]] = {c: [] for c in consumers}
for i, p in enumerate(partitions):
mapping[consumers[i % len(consumers)]].append(p)
return mapping

def process_with_crash(records: list[int], commit_at: int | None) -> tuple[list[int], int]:
processed = records[:commit_at] if commit_at is not None else records
committed = commit_at or 0
return processed, committed

def main() -> None:
parts = list(range(6))
print("=== Initial assign ===", assign(parts, ["c0", "c1"]))
print("=== After join c2 ===", assign(parts, ["c0", "c1", "c2"]))
records = [1, 2, 3, 4]
seen, committed = process_with_crash(records, commit_at=2) # crash before commit
redelivered = records[committed:]
print(f"processed={seen} committed={committed} redelivered={redelivered} duplicates={len(seen)}")

if __name__ == "__main__":
main()

